import { defineStore } from 'pinia'
import { hotStore } from './hmr'
import { markRaw } from 'vue'

export const useUiStore = defineStore('ui', {
  state: () => ({
    // какая панель открыта: null | 'maps' | 'audio'
    panel: null,
    // открыта ли панель наведением (тогда закрывается, когда мышь уходит)
    panelByHover: false,
    // редактор карты: null — закрыт, 'new' — новая, иначе id карты
    editor: null,
    // редактор музыки: null — закрыт, 'new' — добавление, иначе id трека
    audioEditor: null,
    // файлы, с которыми открыть окно добавления (например, перетащенные на экран)
    audioEditorFiles: [],
    // пользователь недавно двигал мышь / касался экрана
    awake: true,
    fullscreen: false
  }),

  getters: {
    anyModal: (s) => s.editor !== null || s.audioEditor !== null,
    anyOverlay() {
      return this.panel !== null || this.anyModal
    }
  },

  actions: {
    openPanel(name, { hover = false } = {}) {
      if (this.anyModal) return
      this.panel = name
      this.panelByHover = hover
    },
    togglePanel(name) {
      if (this.panel === name && !this.panelByHover) this.closePanel()
      else this.openPanel(name)
    },
    closePanel() {
      this.panel = null
      this.panelByHover = false
    },
    openEditor(target) {
      this.closePanel()
      this.audioEditor = null
      this.editor = target
    },
    closeEditor() {
      this.editor = null
    },
    /** target: 'new' или id трека; files — File[] для предзаполнения */
    openAudioEditor(target = 'new', files = []) {
      this.editor = null
      // при открытии из панели музыки саму панель оставляем — после закрытия окна вернёмся к ней
      this.panelByHover = false
      this.audioEditorFiles = markRaw([...files])
      this.audioEditor = target
    },
    closeAudioEditor() {
      this.audioEditor = null
      this.audioEditorFiles = []
    }
  }
})

hotStore(import.meta.webpackHot, useUiStore)
