// Форматы, которые умеют играть браузеры. mp3/ogg/wav/m4a/aac/webm/opus/flac — Chrome, Edge, Firefox;
// в Safari ogg-контейнер может не играть — тогда трек покажет ошибку.
export const AUDIO_EXTENSIONS = ['mp3', 'ogg', 'oga', 'opus', 'wav', 'flac', 'aac', 'm4a', 'mp4', 'webm', 'weba']

export const AUDIO_ACCEPT = ['audio/*', ...AUDIO_EXTENSIONS.map((e) => '.' + e)].join(',')

export function isAudioFile(file) {
  if (!file) return false
  if (file.type && file.type.startsWith('audio/')) return true
  const ext = (file.name.split('.').pop() || '').toLowerCase()
  return AUDIO_EXTENSIONS.includes(ext)
}

/** Все аудиофайлы из DataTransfer (drag&drop) */
export function audioFromTransfer(dt) {
  if (!dt) return []
  return [...(dt.files || [])].filter(isAudioFile)
}

/** Во время перетаскивания имена файлов недоступны, но MIME-типы обычно есть */
export function transferLooksLikeAudio(dt) {
  return !!dt && [...(dt.items || [])].some((i) => i.kind === 'file' && i.type.startsWith('audio/'))
}
