// Все аудиофайлы из src/assets/audio находятся автоматически при сборке.
// Папка первого уровня = категория, вложенные папки дают «Категория / Подпапка».
const ctx = require.context(
  '@/assets/audio',
  true,
  /\.(mp3|ogg|oga|opus|wav|flac|aac|m4a|webm|weba)$/i
)

export const ROOT_CATEGORY = 'Разное'

/** «01 - Шумный_зал.mp3» → «Шумный зал» */
export function prettifyTrackName(fileName) {
  const name = fileName
    .replace(/\.[^.]+$/, '')
    .replace(/[_]+/g, ' ')
    .replace(/^\d+[\s.-]+/, '')
    .trim()
  return name || fileName
}

const stripExt = (path) => path.replace(/\.[^./]+$/, '')

function buildStaticTracks() {
  return (
    ctx
      .keys()
      // require.context отдаёт и './a.mp3', и 'src/assets/audio/a.mp3' — берём только относительные
      .filter((key) => key.startsWith('./'))
      .map((key) => {
        const id = key.slice(2) // 'Таверна/Шумный зал.mp3'
        const parts = id.split('/')
        const file = parts.pop()
        const mod = ctx(key)
        return {
          id,
          name: prettifyTrackName(file),
          file,
          category: parts.length ? parts.join(' / ') : ROOT_CATEGORY,
          url: mod && mod.default ? mod.default : mod,
          temporary: false
        }
      })
      // сравниваем без расширения, иначе «tavern_fun.mp3» оказывается раньше «tavern.mp3»
      .sort((a, b) => stripExt(a.id).localeCompare(stripExt(b.id), 'ru', { numeric: true }))
  )
}

/** Группировка треков по категориям, «Разное» всегда в конце */
export function groupByCategory(tracks) {
  const byCategory = new Map()
  for (const track of tracks) {
    if (!byCategory.has(track.category)) byCategory.set(track.category, [])
    byCategory.get(track.category).push(track)
  }
  return [...byCategory.entries()]
    .sort(([a], [b]) => {
      if (a === ROOT_CATEGORY) return 1
      if (b === ROOT_CATEGORY) return -1
      return a.localeCompare(b, 'ru')
    })
    .map(([name, list]) => ({ name, tracks: list }))
}

export const staticTracks = buildStaticTracks()
const staticById = new Map(staticTracks.map((t) => [t.id, t]))

/** Есть ли такой файл в src/assets/audio (для проверки пресетов) */
export function hasStaticTrack(id) {
  return staticById.has(id)
}

/** Первый трек категории с указанным именем (без учёта регистра) */
export function firstTrackOfCategory(name) {
  const lower = name.toLowerCase()
  return staticTracks.find((t) => t.category.toLowerCase() === lower) || null
}
