import { createRouter, createWebHashHistory } from 'vue-router'
import { useMapsStore } from '@/stores/maps'
import MapView from '@/views/MapView.vue'

const routes = [
  {
    path: '/map/:id',
    name: 'map',
    component: MapView,
    props: true,
    beforeEnter: (to) => {
      const maps = useMapsStore()
      // карты из прошлой сессии после перезагрузки не существуют — уводим на первую
      if (!maps.byId(to.params.id)) return maps.first ? `/map/${maps.first.id}` : true
    }
  },
  {
    path: '/:pathMatch(.*)*',
    redirect: () => {
      const maps = useMapsStore()
      return maps.first ? `/map/${maps.first.id}` : '/map/none'
    }
  }
]

// hash-история: работает и на любом статическом хостинге, и при открытии dist/index.html с диска
const router = createRouter({
  history: createWebHashHistory(),
  routes
})

export default router
