<template>
  <div
    class="app"
    :class="{ 'is-idle': !ui.awake && !ui.anyOverlay }"
    @dragenter="onDragEnter"
    @dragover.prevent="onDragOver"
    @dragleave="onDragLeave"
    @drop.prevent="onDrop"
  >
    <!-- карта на весь экран, при переключении плавно сменяется -->
    <router-view v-slot="{ Component, route: r }">
      <Transition name="map-fade">
        <component :is="Component" :key="r.params.id" />
      </Transition>
    </router-view>

    <!-- зоны у краёв: навёл мышь — выехало меню -->
    <div class="edge edge--left" @mouseenter="hoverEdge('maps')" @mouseleave="cancelHover" />
    <div class="edge edge--right" @mouseenter="hoverEdge('audio')" @mouseleave="cancelHover" />

    <!-- маленькие кнопки поверх карты, видны только когда двигаешь мышью -->
    <div class="hud" :class="{ 'is-visible': ui.awake && !ui.anyOverlay }">
      <button class="hud__btn hud__btn--tl" title="Карты (M)" @click="ui.togglePanel('maps')">
        <AppIcon name="menu" />
      </button>

      <button class="hud__btn hud__btn--tr" title="Музыка (A)" @click="ui.togglePanel('audio')">
        <AppIcon name="music" />
        <span v-if="audio.playingIds.length" class="hud__dot" />
      </button>

      <div v-if="currentMap" class="hud__title">
        <span>{{ currentMap.icon }}</span> {{ currentMap.name }}
        <span v-if="nowPlaying" class="hud__track"><AppIcon name="music" :size="13" /> {{ nowPlaying }}</span>
      </div>

      <div class="hud__tools">
        <button v-if="zoomed" class="hud__btn" title="Сбросить масштаб (0)" @click="resetView">
          <AppIcon name="focus" />
        </button>
        <button v-if="currentMap" class="hud__btn" title="Настройки карты (E)" @click="ui.openEditor(currentMap.id)">
          <AppIcon name="settings" />
        </button>
        <button class="hud__btn" :title="ui.fullscreen ? 'Выйти из полноэкранного (F)' : 'Полный экран (F)'" @click="toggleFullscreen">
          <AppIcon name="fullscreen" />
        </button>
      </div>
    </div>

    <MapsPanel />
    <AudioPanel />
    <MapEditor />
    <AudioEditor />

    <!-- клик мимо открытой панели закрывает её -->
    <div v-if="ui.panel && !ui.panelByHover" class="scrim" @pointerdown="ui.closePanel()" />

    <Transition name="fade">
      <div v-if="dropActive" class="drop-overlay">
        <div class="drop-overlay__box">
          <AppIcon :name="dropKind === 'audio' ? 'music' : 'image'" :size="48" />
          <p v-if="dropKind === 'audio'">Отпустите, чтобы добавить музыку</p>
          <p v-else>Отпустите, чтобы поставить на карту «{{ currentMap?.name }}»</p>
        </div>
      </div>
    </Transition>

    <Transition name="fade">
      <button v-if="audio.blocked" class="sound-hint" @click="audio.unlock()">
        <AppIcon name="volume" :size="18" /> Нажмите в любом месте, чтобы включить звук
      </button>
    </Transition>

    <Transition name="fade">
      <div v-if="toast" class="toast">{{ toast }}</div>
    </Transition>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useMapsStore, imageFromFile } from '@/stores/maps'
import { useAudioStore } from '@/stores/audio'
import { useUiStore } from '@/stores/ui'
import { useIdle } from '@/composables/useIdle'
import { useEdgeSwipe } from '@/composables/useEdgeSwipe'
import { imageFromTransfer, transferHasFiles } from '@/composables/imageFiles'
import { audioFromTransfer, transferLooksLikeAudio } from '@/composables/audioFiles'
import AppIcon from '@/components/AppIcon.vue'
import MapsPanel from '@/components/MapsPanel.vue'
import AudioPanel from '@/components/AudioPanel.vue'
import MapEditor from '@/components/MapEditor.vue'
import AudioEditor from '@/components/AudioEditor.vue'

const maps = useMapsStore()
const audio = useAudioStore()
const ui = useUiStore()
const route = useRoute()
const router = useRouter()

useIdle(2500)

const currentMap = computed(() => maps.byId(route.params.id))
const zoomed = computed(() => {
  const v = currentMap.value && currentMap.value.view
  return v && (v.scale !== 1 || v.x !== 0 || v.y !== 0)
})
const nowPlaying = computed(() => {
  const ids = audio.playingIds
  if (!ids.length) return ''
  const name = audio.track(ids[0])?.name || ''
  return ids.length > 1 ? `${name} +${ids.length - 1}` : name
})

// смена карты → её музыка
watch(
  () => currentMap.value && currentMap.value.id,
  (id) => id && audio.applyMapAudio(currentMap.value),
  { immediate: true }
)

// ---------- всплывающие подсказки ----------
const toast = ref('')
let toastTimer = null
function showToast(text) {
  toast.value = text
  clearTimeout(toastTimer)
  toastTimer = setTimeout(() => (toast.value = ''), 2200)
}

// ---------- наведение на края ----------
let hoverTimer = null
function hoverEdge(panel) {
  if (ui.panel || ui.anyModal) return
  clearTimeout(hoverTimer)
  hoverTimer = setTimeout(() => ui.openPanel(panel, { hover: true }), 180)
}
function cancelHover() {
  clearTimeout(hoverTimer)
}

// ---------- свайпы для сенсорного стола ----------
useEdgeSwipe((side) => {
  if (ui.anyModal) return
  const panel = side === 'left' ? 'maps' : 'audio'
  if (ui.panel === panel) return
  if (ui.panel) ui.closePanel()
  else ui.openPanel(panel)
})

// ---------- файлы перетаскиванием прямо на экран ----------
// картинка → на текущую карту, аудио → окно добавления музыки
const dropActive = ref(false)
const dropKind = ref('image')
let dragDepth = 0

function onDragEnter(e) {
  if (ui.anyModal || !transferHasFiles(e.dataTransfer)) return
  if (dragDepth === 0) dropKind.value = transferLooksLikeAudio(e.dataTransfer) ? 'audio' : 'image'
  dragDepth++
  dropActive.value = true
}
function onDragOver(e) {
  if (dropActive.value) e.dataTransfer.dropEffect = 'copy'
}
function onDragLeave() {
  if (!dropActive.value) return
  dragDepth = Math.max(0, dragDepth - 1)
  if (dragDepth === 0) dropActive.value = false
}
function onDrop(e) {
  const wasActive = dropActive.value
  dropActive.value = false
  dragDepth = 0
  if (!wasActive) return
  const audioFiles = audioFromTransfer(e.dataTransfer)
  const image = imageFromTransfer(e.dataTransfer)
  if (image && currentMap.value) setCurrentImage(image)
  if (audioFiles.length) ui.openAudioEditor('new', audioFiles)
  else if (!image) showToast('Можно перетащить изображение или аудиофайлы')
}

function setCurrentImage(file) {
  if (!file) {
    showToast('Это не изображение')
    return
  }
  maps.setImage(currentMap.value.id, imageFromFile(file))
  showToast(`Изображение для «${currentMap.value.name}» обновлено`)
}

function onPaste(e) {
  if (ui.anyModal || !currentMap.value) return
  const file = imageFromTransfer(e.clipboardData)
  if (file) {
    e.preventDefault()
    setCurrentImage(file)
  }
}

// ---------- полный экран ----------
function toggleFullscreen() {
  if (document.fullscreenElement) document.exitFullscreen()
  else document.documentElement.requestFullscreen().catch(() => showToast('Браузер не разрешил полный экран — нажмите F11'))
}
function onFullscreenChange() {
  ui.fullscreen = !!document.fullscreenElement
}

function resetView() {
  if (currentMap.value) maps.resetView(currentMap.value.id)
}

// ---------- горячие клавиши ----------
// e.code, а не e.key — чтобы работало и в русской раскладке
function onKey(e) {
  if (ui.anyModal) return // у окон свои клавиши
  if (e.ctrlKey || e.metaKey || e.altKey) return
  const tag = (e.target.tagName || '').toLowerCase()
  if (tag === 'input' || tag === 'textarea' || tag === 'select') return

  const digit = /^Digit([0-9])$/.exec(e.code) || /^Numpad([0-9])$/.exec(e.code)
  if (digit) {
    const n = +digit[1]
    if (n === 0) return resetView()
    const map = maps.maps[n - 1]
    if (map) router.push(`/map/${map.id}`)
    return
  }

  switch (e.code) {
    case 'KeyM':
    case 'Tab':
      e.preventDefault()
      ui.togglePanel('maps')
      break
    case 'KeyA':
    case 'KeyS':
      ui.togglePanel('audio')
      break
    // preventDefault — иначе буква «впечатается» в поле названия, которое получит фокус
    case 'KeyE':
      e.preventDefault()
      if (currentMap.value) ui.openEditor(currentMap.value.id)
      break
    case 'KeyN':
      e.preventDefault()
      if (e.shiftKey) ui.openAudioEditor('new')
      else ui.openEditor('new')
      break
    case 'KeyF':
      toggleFullscreen()
      break
    case 'Space':
      e.preventDefault()
      audio.togglePauseAll()
      break
    case 'ArrowRight':
    case 'ArrowLeft': {
      const i = maps.maps.findIndex((m) => m.id === route.params.id)
      const next = maps.maps[(i + (e.code === 'ArrowRight' ? 1 : -1) + maps.maps.length) % maps.maps.length]
      if (next) router.push(`/map/${next.id}`)
      break
    }
    case 'Escape':
      ui.closePanel()
      break
  }
}

// первый клик по странице разрешает браузеру играть звук
function onFirstGesture() {
  audio.unlock()
}

onMounted(() => {
  window.addEventListener('keydown', onKey)
  window.addEventListener('paste', onPaste)
  window.addEventListener('pointerdown', onFirstGesture)
  document.addEventListener('fullscreenchange', onFullscreenChange)
})
onBeforeUnmount(() => {
  window.removeEventListener('keydown', onKey)
  window.removeEventListener('paste', onPaste)
  window.removeEventListener('pointerdown', onFirstGesture)
  document.removeEventListener('fullscreenchange', onFullscreenChange)
})
</script>

<style>
.app {
  position: fixed;
  inset: 0;
}
.app.is-idle,
.app.is-idle * {
  cursor: none !important;
}

/* смена карт — наплыв */
.map-fade-enter-active,
.map-fade-leave-active {
  transition: opacity 0.6s ease;
}
.map-fade-enter-from,
.map-fade-leave-to {
  opacity: 0;
}

.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.25s;
}
.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}

.edge {
  position: fixed;
  top: 0;
  bottom: 0;
  z-index: 20;
  width: 6px;
}
.edge--left {
  left: 0;
}
.edge--right {
  right: 0;
}

.scrim {
  position: fixed;
  inset: 0;
  z-index: 25;
}

/* ---------- HUD ---------- */
.hud {
  opacity: 0;
  transition: opacity 0.5s;
  pointer-events: none;
}
.hud.is-visible {
  opacity: 1;
}
.hud.is-visible .hud__btn {
  pointer-events: auto;
}

.hud__btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid rgba(199, 154, 69, 0.5);
  border-radius: 50%;
  background: rgba(20, 12, 7, 0.72);
  color: var(--brass-light);
  cursor: pointer;
  backdrop-filter: blur(4px);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5);
  transition: background 0.15s, transform 0.15s, border-color 0.15s;
}
.hud__btn:hover {
  background: rgba(58, 36, 21, 0.92);
  border-color: var(--brass);
  transform: scale(1.06);
}
.hud__btn--tl,
.hud__btn--tr {
  position: fixed;
  top: 16px;
  z-index: 15;
}
.hud__btn--tl {
  left: 16px;
}
.hud__btn--tr {
  right: 16px;
}
.hud__dot {
  position: absolute;
  top: 7px;
  right: 7px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ember);
  box-shadow: 0 0 8px var(--ember);
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  50% { opacity: 0.35; }
}

.hud__title {
  position: fixed;
  left: 16px;
  bottom: 16px;
  z-index: 15;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  max-width: calc(100vw - 220px);
  padding: 0.45rem 1rem;
  border: 1px solid rgba(199, 154, 69, 0.4);
  border-radius: 999px;
  background: rgba(20, 12, 7, 0.72);
  backdrop-filter: blur(4px);
  font-variant: small-caps;
  letter-spacing: 0.06em;
  color: var(--parchment);
  white-space: nowrap;
  overflow: hidden;
}
.hud__track {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-left: 0.4rem;
  padding-left: 0.7rem;
  border-left: 1px solid rgba(199, 154, 69, 0.35);
  font-variant: normal;
  letter-spacing: 0;
  font-size: 0.85rem;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
}

.hud__tools {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 15;
  display: flex;
  gap: 0.5rem;
}

/* ---------- оверлеи ---------- */
.drop-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  background: rgba(10, 6, 3, 0.75);
  pointer-events: none;
}
.drop-overlay__box {
  display: grid;
  justify-items: center;
  gap: 0.5rem;
  padding: 3rem 4rem;
  border: 3px dashed var(--brass);
  border-radius: 20px;
  color: var(--brass-light);
  font-size: 1.3rem;
}

.sound-hint {
  position: fixed;
  left: 50%;
  top: 18px;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transform: translateX(-50%);
  padding: 0.6rem 1.2rem;
  border: 1px solid var(--ember);
  border-radius: 999px;
  background: rgba(20, 12, 7, 0.9);
  color: var(--parchment);
  cursor: pointer;
  box-shadow: 0 0 20px var(--ember-glow);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 80px;
  z-index: 70;
  transform: translateX(-50%);
  padding: 0.6rem 1.2rem;
  border: 1px solid var(--brass-dark);
  border-radius: 8px;
  background: rgba(20, 12, 7, 0.92);
  color: var(--parchment);
  pointer-events: none;
}
</style>
