// Картинки для пресетов: src/assets/maps/<id>.<ext>
const ctx = require.context(
  '@/assets/maps',
  false,
  /\.(png|jpe?g|jfif|gif|webp|avif|apng|bmp|ico|svg)$/i
)

const images = new Map()
for (const key of ctx.keys()) {
  if (!key.startsWith('./')) continue
  const file = key.slice(2)
  const mod = ctx(key)
  const url = mod && mod.default ? mod.default : mod
  images.set(file.toLowerCase(), { file, url })
  // по имени без расширения тоже ищем: 'tavern' → tavern.jpg
  const base = file.replace(/\.[^.]+$/, '').toLowerCase()
  if (!images.has(base)) images.set(base, { file, url })
}

/** @returns {{file: string, url: string} | null} */
export function findPresetImage(nameOrId) {
  if (!nameOrId) return null
  return images.get(String(nameOrId).toLowerCase()) || null
}
