<template>
  <div
    ref="stageEl"
    class="stage"
    :class="{ 'is-dragging': dragging, 'has-image': showImage }"
    @wheel.prevent="onWheel"
    @pointerdown="onDown"
    @pointermove="onMove"
    @pointerup="onUp"
    @pointercancel="onUp"
    @dblclick="resetView"
  >
    <div v-if="showImage" class="frame" :style="frameStyle">
      <img
        :key="map.image.url"
        class="frame__img"
        :src="map.image.url"
        :alt="map.name"
        :style="{ objectFit: map.fit }"
        draggable="false"
        @error="failed = map.image.url"
      />
    </div>

    <MapPlaceholder v-else :map="map" :error="failed ? 'Браузер не смог открыть этот файл' : ''" />
  </div>
</template>

<script setup>
import { computed, ref } from 'vue'
import { useMapsStore } from '@/stores/maps'
import MapPlaceholder from './MapPlaceholder.vue'

const props = defineProps({
  map: { type: Object, required: true }
})

const maps = useMapsStore()
const stageEl = ref(null)
const failed = ref(null)
const dragging = ref(false)

const MIN_SCALE = 0.2
const MAX_SCALE = 10
const EDGE = 32 // зона свайпа от края — её не перехватываем

const showImage = computed(() => props.map.image && failed.value !== props.map.image.url)
const view = computed(() => props.map.view)

const frameStyle = computed(() => {
  const { x, y, scale } = view.value
  const rotated = props.map.rotation % 180 !== 0
  return {
    // при повороте на 90° меняем стороны рамки местами, чтобы картинка вписывалась в экран
    width: rotated ? '100vh' : '100vw',
    height: rotated ? '100vw' : '100vh',
    transform: `translate(-50%, -50%) translate(${x}px, ${y}px) scale(${scale}) rotate(${props.map.rotation}deg)`
  }
})

const clamp = (v, min, max) => Math.min(max, Math.max(min, v))

function setView(next) {
  maps.setView(props.map.id, next)
}

function resetView() {
  maps.resetView(props.map.id)
}

/** координаты точки относительно центра сцены */
function fromCenter(clientX, clientY) {
  const r = stageEl.value.getBoundingClientRect()
  return { x: clientX - r.left - r.width / 2, y: clientY - r.top - r.height / 2 }
}

/** масштабировать вокруг точки p так, чтобы она осталась под курсором/пальцами */
function zoomAround(base, p, newScale) {
  const scale = clamp(newScale, MIN_SCALE, MAX_SCALE)
  const k = scale / base.scale
  return { scale, x: p.x - (p.x - base.x) * k, y: p.y - (p.y - base.y) * k }
}

function onWheel(e) {
  if (!showImage.value) return
  const factor = Math.exp(-e.deltaY * (e.ctrlKey ? 0.01 : 0.0015))
  setView(zoomAround(view.value, fromCenter(e.clientX, e.clientY), view.value.scale * factor))
}

// ---------- перетаскивание и пинч ----------
const pointers = new Map()
let gesture = null

function beginGesture() {
  const pts = [...pointers.values()]
  const base = { ...view.value }
  if (pts.length === 1) {
    gesture = { type: 'pan', start: pts[0], base }
  } else if (pts.length >= 2) {
    const [a, b] = pts
    gesture = {
      type: 'pinch',
      dist: Math.hypot(a.x - b.x, a.y - b.y) || 1,
      mid: fromCenter((a.x + b.x) / 2, (a.y + b.y) / 2),
      base
    }
  } else {
    gesture = null
  }
  dragging.value = !!gesture
}

function onDown(e) {
  if (!showImage.value) return
  if (e.pointerType === 'mouse' && e.button !== 0) return
  if (e.pointerType !== 'mouse' && (e.clientX < EDGE || e.clientX > window.innerWidth - EDGE)) return
  stageEl.value.setPointerCapture(e.pointerId)
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY })
  beginGesture()
}

function onMove(e) {
  if (!pointers.has(e.pointerId) || !gesture) return
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY })
  const { base } = gesture

  if (gesture.type === 'pan') {
    const p = pointers.get(e.pointerId)
    setView({ ...base, x: base.x + p.x - gesture.start.x, y: base.y + p.y - gesture.start.y })
  } else {
    const [a, b] = [...pointers.values()]
    const dist = Math.hypot(a.x - b.x, a.y - b.y)
    const mid = fromCenter((a.x + b.x) / 2, (a.y + b.y) / 2)
    // сначала зум вокруг стартовой середины, затем сдвиг вслед за пальцами
    const zoomed = zoomAround(base, gesture.mid, (base.scale * dist) / gesture.dist)
    setView({ ...zoomed, x: zoomed.x + mid.x - gesture.mid.x, y: zoomed.y + mid.y - gesture.mid.y })
  }
}

function onUp(e) {
  if (!pointers.delete(e.pointerId)) return
  beginGesture()
}
</script>

<style scoped>
.stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #000;
}
.stage.has-image {
  cursor: grab;
}
.stage.is-dragging {
  cursor: grabbing;
}

.frame {
  position: absolute;
  left: 50%;
  top: 50%;
  transform-origin: center center;
  will-change: transform;
}

.frame__img {
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
</style>
