import { acceptHMRUpdate } from 'pinia'

const isPlainObject = (v) => Object.prototype.toString.call(v) === '[object Object]'

/**
 * Горячая замена Pinia-стора под webpack (только dev-режим).
 *
 * Штатный acceptHMRUpdate рассчитан на Vite: там колбэк accept получает новый модуль.
 * В webpack колбэк accept — это обработчик ошибок, поэтому делаем иначе: модуль стора
 * принимает себя сам, при перезапуске забирает pinia из hot.data и обновляет
 * существующий стор на месте. Без этого после правки стора страница работает со старой
 * версией (новых полей/методов нет) до перезагрузки.
 *
 * Вызов в конце файла стора: hotStore(import.meta.webpackHot, useXxxStore)
 */
export function hotStore(hot, useStore) {
  if (!hot) return
  hot.accept()

  const pinia = hot.data && hot.data.pinia
  const store = pinia && pinia._s.get(useStore.$id)
  if (store) {
    const before = { ...store.$state }
    acceptHMRUpdate(useStore, hot)({ [useStore.$id]: useStore })
    // Pinia переносит объекты только по ключам из нового начального состояния, поэтому
    // словари с динамическими ключами (active: { [id]: 'playing' } и т.п.) обнулились бы — дольём
    for (const key in before) {
      const was = before[key]
      const now = store.$state[key]
      if (was !== now && isPlainObject(was) && isPlainObject(now)) {
        for (const k in was) if (!(k in now)) now[k] = was[k]
      }
    }
  }

  hot.dispose((data) => {
    data.pinia = useStore._pinia || pinia
  })
}
