import { defineStore } from 'pinia'
import { hotStore } from './hmr'
import { staticTracks, groupByCategory, prettifyTrackName } from '@/library/audioLibrary'
import { useMapsStore } from './maps'

export const UPLOAD_CATEGORY = 'Загруженное'

const FADE_MS = 1500
const DEFAULT_TRACK_VOLUME = 0.8
const STORAGE_KEY = 'dnd-screen:audio'

// HTMLAudioElement-ы держим вне реактивного состояния.
// При горячей замене модуля (dev) забираем каналы у старой версии, иначе играющий трек нельзя будет остановить
const hot = import.meta.webpackHot
const channels = (hot && hot.data && hot.data.channels) || new Map() // id -> { el, fade, target, from, startedAt, duration }
if (hot) hot.dispose((data) => (data.channels = channels))
let rafId = null

function loadPrefs() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}
  } catch (e) {
    return {}
  }
}

function savePrefs(state) {
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        master: state.master,
        muted: state.muted,
        autoMapAudio: state.autoMapAudio,
        // громкость загруженных треков после перезагрузки не нужна — самих треков уже не будет
        volumes: Object.fromEntries(
          Object.entries(state.volumes).filter(([id]) => !id.startsWith('upload:'))
        )
      })
    )
  } catch (e) {
    /* приватный режим и т.п. — просто не запоминаем */
  }
}

export const useAudioStore = defineStore('audio', {
  state: () => {
    const prefs = loadPrefs()
    return {
      // файлы из src/assets/audio + загруженные в этой сессии (temporary: true)
      tracks: staticTracks.map((t) => ({ ...t })),
      master: prefs.master ?? 0.8,
      muted: prefs.muted ?? false,
      autoMapAudio: prefs.autoMapAudio ?? true,
      volumes: prefs.volumes ?? {}, // громкость каждого трека, id -> 0..1
      active: {}, // id -> 'playing' | 'stopping'
      blocked: false, // браузер не дал стартовать без клика
      paused: [], // что играло перед «паузой всего» (пробел)
      errors: {} // id -> текст ошибки
    }
  },

  getters: {
    playingIds: (s) => Object.keys(s.active).filter((id) => s.active[id] === 'playing'),
    isPlaying: (s) => (id) => s.active[id] === 'playing',
    volumeOf: (s) => (id) => s.volumes[id] ?? DEFAULT_TRACK_VOLUME,
    byId: (s) => new Map(s.tracks.map((t) => [t.id, t])),
    track() {
      return (id) => this.byId.get(id) || null
    },
    categories: (s) => groupByCategory(s.tracks),
    categoryNames() {
      return this.categories.map((c) => c.name)
    }
  },

  actions: {
    // ---------- библиотека (как у карт: живёт до перезагрузки) ----------

    /**
     * Добавить загруженные файлы.
     * @param {{file: File, name?: string}[]} items
     * @returns {string[]} id новых треков
     */
    addTracks(items, category = UPLOAD_CATEGORY) {
      const ids = items.map(({ file, name }) => {
        const id = `upload:${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`
        this.tracks.push({
          id,
          name: (name || '').trim() || prettifyTrackName(file.name),
          file: file.name,
          category: category.trim() || UPLOAD_CATEGORY,
          url: URL.createObjectURL(file),
          temporary: true
        })
        return id
      })
      return ids
    },

    /** Переименовать / сменить категорию / заменить файл (file — новый File) */
    updateTrack(id, { name, category, file } = {}) {
      const track = this.track(id)
      if (!track) return
      if (name !== undefined) track.name = name.trim() || track.name
      if (category !== undefined) track.category = category.trim() || UPLOAD_CATEGORY
      if (file) {
        const wasPlaying = this.isPlaying(id)
        this._dropChannel(id)
        if (track.temporary) URL.revokeObjectURL(track.url)
        track.url = URL.createObjectURL(file)
        track.file = file.name
        track.temporary = true
        delete this.errors[id]
        if (wasPlaying) this.play(id, { exclusive: false })
      }
    },

    removeTrack(id) {
      const index = this.tracks.findIndex((t) => t.id === id)
      if (index === -1) return
      const [track] = this.tracks.splice(index, 1)
      this._dropChannel(id)
      if (track.temporary) URL.revokeObjectURL(track.url)
      delete this.volumes[id]
      delete this.errors[id]
      this.paused = this.paused.filter((p) => p !== id)
      useMapsStore().forgetTrack(id)
    },

    // ---------- воспроизведение ----------

    /** Включить трек. exclusive — остальные плавно гаснут (обычный режим). */
    play(id, { exclusive = true } = {}) {
      if (!this.byId.has(id)) return
      if (exclusive) {
        for (const other of Object.keys(this.active)) {
          if (other !== id) this.stop(other)
        }
      }
      this.paused = []
      this._fadeIn(id)
    },

    /** Добавить/убрать трек поверх текущих, не трогая остальные */
    toggleLayer(id) {
      if (this.isPlaying(id)) this.stop(id)
      else this.play(id, { exclusive: false })
    },

    toggle(id) {
      if (this.isPlaying(id)) this.stop(id)
      else this.play(id)
    },

    stop(id) {
      if (!this.active[id]) return
      this.active[id] = 'stopping'
      this._fadeTo(id, 0)
    },

    stopAll() {
      Object.keys(this.active).forEach((id) => this.stop(id))
    },

    /** Пробел: пауза всего / вернуть то, что играло */
    togglePauseAll() {
      if (this.playingIds.length) {
        this.paused = [...this.playingIds]
        this.stopAll()
      } else if (this.paused.length) {
        const ids = this.paused
        this.paused = []
        this.setScene(ids)
      }
    },

    /** Играет ровно этот набор треков, остальное плавно уходит */
    setScene(ids) {
      const wanted = new Set(ids.filter((id) => this.byId.has(id)))
      for (const id of Object.keys(this.active)) {
        if (!wanted.has(id)) this.stop(id)
      }
      wanted.forEach((id) => {
        if (!this.isPlaying(id)) this._fadeIn(id)
      })
      this.paused = []
    },

    /** Звук при переходе на карту */
    applyMapAudio(map) {
      if (!this.autoMapAudio || !map) return
      const { mode, tracks } = map.audio
      if (mode === 'stop') this.stopAll()
      else if (mode === 'tracks' && tracks.length) this.setScene(tracks)
      // 'keep' — ничего не меняем
    },

    setTrackVolume(id, value) {
      this.volumes[id] = value
      this._applyVolume(id)
      savePrefs(this)
    },

    setMaster(value) {
      this.master = value
      if (value > 0) this.muted = false
      this._applyAllVolumes()
      savePrefs(this)
    },

    toggleMute() {
      this.muted = !this.muted
      this._applyAllVolumes()
      savePrefs(this)
    },

    setAutoMapAudio(value) {
      this.autoMapAudio = value
      savePrefs(this)
    },

    /** После первого клика пользователя повторяем то, что не дал запустить браузер */
    unlock() {
      if (!this.blocked) return
      this.blocked = false
      for (const [id, ch] of channels) {
        if (this.active[id] === 'playing') this._startElement(id, ch)
      }
    },

    // ---------- внутреннее ----------

    _channel(id) {
      let ch = channels.get(id)
      if (!ch) {
        const track = this.track(id)
        const el = new Audio(track.url)
        el.loop = true // никаких автопереключений — всё крутится по кругу
        el.preload = 'auto'
        el.addEventListener('error', () => {
          if (channels.get(id) !== ch) return // канал уже заменён/удалён
          this.errors[id] = 'Не удалось воспроизвести файл (формат не поддерживается браузером?)'
          delete this.active[id]
        })
        ch = { el, fade: 0, from: 0, target: 0, startedAt: 0, duration: FADE_MS }
        channels.set(id, ch)
      }
      return ch
    },

    /** мгновенно остановить и забыть HTMLAudioElement (при удалении/замене файла) */
    _dropChannel(id) {
      const ch = channels.get(id)
      if (!ch) return
      channels.delete(id)
      ch.el.pause()
      ch.el.removeAttribute('src')
      ch.el.load()
      delete this.active[id]
    },

    _fadeIn(id) {
      const ch = this._channel(id)
      delete this.errors[id]
      this.active[id] = 'playing'
      this._startElement(id, ch)
      this._fadeTo(id, 1)
    },

    _startElement(id, ch) {
      if (!ch.el.paused) return
      const p = ch.el.play()
      if (p && p.catch) {
        p.catch((err) => {
          if (err && err.name === 'NotAllowedError') this.blocked = true
          else if (err && err.name !== 'AbortError') this.errors[id] = err.message
        })
      }
    },

    _fadeTo(id, target) {
      const ch = channels.get(id)
      if (!ch) return
      ch.from = ch.fade
      ch.target = target
      ch.startedAt = performance.now()
      ch.duration = FADE_MS * Math.abs(target - ch.fade) || 1
      this._tick()
    },

    _tick() {
      if (rafId) return
      const step = (now) => {
        let busy = false
        for (const [id, ch] of channels) {
          if (ch.fade === ch.target) continue
          const t = Math.min(1, (now - ch.startedAt) / ch.duration)
          ch.fade = ch.from + (ch.target - ch.from) * t
          if (t >= 1) {
            ch.fade = ch.target
            if (ch.target === 0) {
              ch.el.pause()
              if (this.active[id] === 'stopping') delete this.active[id]
            }
          } else {
            busy = true
          }
          this._applyVolume(id)
        }
        rafId = busy ? requestAnimationFrame(step) : null
      }
      rafId = requestAnimationFrame(step)
    },

    _applyVolume(id) {
      const ch = channels.get(id)
      if (!ch) return
      const master = this.muted ? 0 : this.master
      // квадрат — громкость на слух ощущается линейнее
      const v = master * master * this.volumeOf(id) * ch.fade
      ch.el.volume = Math.max(0, Math.min(1, v))
    },

    _applyAllVolumes() {
      for (const id of channels.keys()) this._applyVolume(id)
    }
  }
})

hotStore(import.meta.webpackHot, useAudioStore)
