<template>
  <Transition name="modal">
    <div v-if="target" class="backdrop" @pointerdown.self="close">
      <form class="modal panel-surface" @submit.prevent="save">
        <header class="modal__head">
          <h2>{{ isNew ? 'Добавить музыку' : 'Настройки трека' }}</h2>
          <button type="button" class="icon-btn" title="Закрыть (Esc)" @click="close">
            <AppIcon name="close" />
          </button>
        </header>

        <div class="modal__body scroll">
          <!-- файлы -->
          <div
            class="drop drop--compact"
            :class="{ 'is-over': dragOver }"
            @click="pickFiles"
            @dragover.prevent="dragOver = true"
            @dragleave="dragOver = false"
            @drop.prevent="onDrop"
          >
            <div class="drop__hint">
              <AppIcon name="music" :size="30" />
              <span v-if="isNew">Нажмите или перетащите аудиофайлы — можно несколько сразу</span>
              <span v-else>Заменить файл трека</span>
              <small>MP3, OGG, OPUS, WAV, FLAC, M4A, AAC, WEBM</small>
            </div>
            <input ref="fileInput" type="file" :accept="AUDIO_ACCEPT" :multiple="isNew" hidden @change="onFileInput" />
          </div>
          <p v-if="fileError" class="error">{{ fileError }}</p>

          <!-- новые файлы -->
          <TransitionGroup v-if="isNew && pending.length" tag="ul" name="pending" class="pending">
            <li v-for="item in pending" :key="item.key" class="pending__row">
              <button
                type="button"
                class="icon-btn"
                :class="{ 'is-on': previewKey === item.key }"
                :title="previewKey === item.key ? 'Остановить' : 'Прослушать'"
                @click="togglePreview(item)"
              >
                <AppIcon :name="previewKey === item.key ? 'stop' : 'play'" :size="13" />
              </button>
              <div class="pending__text">
                <input v-model="item.name" class="input input--slim" maxlength="60" @keydown.stop />
                <small :title="item.file.name">{{ item.file.name }} · {{ formatSize(item.file.size) }}</small>
              </div>
              <button type="button" class="icon-btn" title="Убрать из списка" @click="removePending(item)">
                <AppIcon name="close" :size="16" />
              </button>
            </li>
          </TransitionGroup>

          <!-- существующий трек -->
          <template v-if="!isNew && track">
            <div class="source">
              <AppIcon name="music" :size="16" />
              <span v-if="track.temporary">Загружен в этой сессии: {{ track.file }}</span>
              <span v-else>Файл проекта: <code>{{ track.id }}</code></span>
              <button
                type="button"
                class="icon-btn"
                :title="audio.isPlaying(track.id) ? 'Остановить' : 'Прослушать'"
                @click="audio.toggle(track.id)"
              >
                <AppIcon :name="audio.isPlaying(track.id) ? 'stop' : 'play'" :size="13" />
              </button>
            </div>
            <p v-if="replacement" class="replace-note">
              Будет заменён на <b>{{ replacement.name }}</b> ({{ formatSize(replacement.size) }})
              <button type="button" class="btn btn--ghost" @click="replacement = null">Отменить</button>
            </p>
            <label class="field">
              <span>Название</span>
              <input ref="nameInput" v-model="editName" class="input" maxlength="60" />
            </label>
          </template>

          <!-- категория -->
          <label class="field">
            <span>Категория</span>
            <input
              v-model="category"
              class="input"
              list="audio-categories"
              maxlength="40"
              placeholder="Например, Бой или Таверна"
            />
            <datalist id="audio-categories">
              <option v-for="name in audio.categoryNames" :key="name" :value="name" />
            </datalist>
          </label>
          <div class="chips">
            <button
              v-for="name in categoryChips"
              :key="name"
              type="button"
              class="chip"
              :class="{ 'is-on': category.trim() === name }"
              @click="category = name"
            >
              {{ name }}
            </button>
          </div>

          <!-- привязка к текущей карте -->
          <label v-if="isNew && currentMap && pending.length" class="bind">
            <input v-model="bindToMap" type="checkbox" />
            <span class="check"><AppIcon name="check" :size="12" /></span>
            <span>
              Привязать к карте «{{ currentMap.name }}»
              <small v-if="pending.length > 1">— все {{ pending.length }} трека будут звучать слоями</small>
            </span>
          </label>
        </div>

        <footer class="modal__foot">
          <button v-if="canDelete" type="button" class="btn btn--danger" @click="remove">
            <AppIcon name="trash" :size="16" /> Удалить
          </button>
          <span class="spacer" />
          <button type="button" class="btn btn--ghost" @click="close">Отмена</button>
          <button type="submit" class="btn btn--primary" :disabled="isNew && !pending.length">
            <AppIcon name="check" :size="16" />
            {{ isNew ? `Добавить${pending.length > 1 ? ` (${pending.length})` : ''}` : 'Сохранить' }}
          </button>
        </footer>
      </form>
    </div>
  </Transition>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useAudioStore, UPLOAD_CATEGORY } from '@/stores/audio'
import { useMapsStore } from '@/stores/maps'
import { useUiStore } from '@/stores/ui'
import { prettifyTrackName } from '@/library/audioLibrary'
import { AUDIO_ACCEPT, isAudioFile, audioFromTransfer } from '@/composables/audioFiles'
import AppIcon from './AppIcon.vue'

const audio = useAudioStore()
const maps = useMapsStore()
const ui = useUiStore()
const route = useRoute()

const target = computed(() => ui.audioEditor)
const isNew = computed(() => target.value === 'new')
const track = computed(() => (isNew.value ? null : audio.track(target.value)))
const canDelete = computed(() => !isNew.value && track.value && track.value.id.startsWith('upload:'))
const currentMap = computed(() => maps.byId(route.params.id))

const fileInput = ref(null)
const nameInput = ref(null)
const dragOver = ref(false)
const fileError = ref('')

const pending = ref([]) // новые файлы: { key, file, name }
const replacement = ref(null) // File для замены существующего трека
const editName = ref('')
const category = ref('')
const bindToMap = ref(false)

const previewKey = ref(null) // какой из новых файлов сейчас прослушивается
let previewEl = null

let lastCategory = UPLOAD_CATEGORY
let keySeq = 0

const categoryChips = computed(() => {
  const names = new Set(audio.categoryNames)
  names.add(UPLOAD_CATEGORY)
  return [...names]
})

// ---------- открытие ----------
watch(
  target,
  (t) => {
    stopPreview()
    if (!t) return
    fileError.value = ''
    pending.value = []
    replacement.value = null
    bindToMap.value = false
    if (isNew.value) {
      category.value = lastCategory
      addFiles(ui.audioEditorFiles)
    } else if (track.value) {
      editName.value = track.value.name
      category.value = track.value.category
      nextTick(() => nameInput.value && nameInput.value.focus())
    }
  },
  { immediate: true }
)

// трек удалили, пока окно открыто
watch(track, (t) => {
  if (target.value && !isNew.value && !t) close()
})

// ---------- файлы ----------
function addFiles(files) {
  const list = [...files]
  const good = list.filter(isAudioFile)
  fileError.value = good.length < list.length ? 'Часть файлов пропущена — это не аудио' : ''
  if (!good.length) return

  if (!isNew.value) {
    replacement.value = good[0]
    return
  }
  for (const file of good) {
    pending.value.push({ key: ++keySeq, file, name: prettifyTrackName(file.name), previewUrl: null })
  }
}

function pickFiles() {
  fileInput.value && fileInput.value.click()
}

function onFileInput(e) {
  addFiles(e.target.files || [])
  e.target.value = ''
}

function onDrop(e) {
  dragOver.value = false
  const files = audioFromTransfer(e.dataTransfer)
  if (files.length) addFiles(files)
  else fileError.value = 'Перетащите аудиофайлы'
}

function removePending(item) {
  if (previewKey.value === item.key) stopPreview()
  if (item.previewUrl) URL.revokeObjectURL(item.previewUrl)
  pending.value = pending.value.filter((p) => p !== item)
}

function releasePending() {
  pending.value.forEach((p) => p.previewUrl && URL.revokeObjectURL(p.previewUrl))
  pending.value = []
}

function formatSize(bytes) {
  if (bytes < 1024 * 1024) return `${Math.max(1, Math.round(bytes / 1024))} КБ`
  return `${(bytes / 1024 / 1024).toFixed(1)} МБ`
}

// ---------- прослушивание до добавления ----------
function togglePreview(item) {
  if (previewKey.value === item.key) return stopPreview()
  stopPreview()
  if (!item.previewUrl) item.previewUrl = URL.createObjectURL(item.file)
  previewEl = new Audio(item.previewUrl)
  previewEl.volume = 0.6
  previewEl.play().catch(() => {
    fileError.value = `Браузер не может воспроизвести «${item.file.name}»`
    stopPreview()
  })
  previewKey.value = item.key
}

function stopPreview() {
  if (previewEl) previewEl.pause()
  previewEl = null
  previewKey.value = null
}

// ---------- сохранение ----------
function close() {
  stopPreview()
  releasePending()
  ui.closeAudioEditor()
}

function save() {
  if (isNew.value) {
    if (!pending.value.length) return
    lastCategory = category.value.trim() || UPLOAD_CATEGORY
    const ids = audio.addTracks(
      pending.value.map((p) => ({ file: p.file, name: p.name })),
      lastCategory
    )
    if (bindToMap.value && currentMap.value) {
      maps.updateMap(currentMap.value.id, { audio: { mode: 'tracks', tracks: ids } })
      audio.applyMapAudio(currentMap.value)
    }
  } else if (track.value) {
    audio.updateTrack(track.value.id, {
      name: editName.value,
      category: category.value,
      file: replacement.value || undefined
    })
  }
  close()
}

function remove() {
  const t = track.value
  if (!t || !window.confirm(`Удалить трек «${t.name}»? Он пропадёт и из привязок карт.`)) return
  audio.removeTrack(t.id)
  close()
}

function onKey(e) {
  if (!target.value) return
  if (e.key === 'Escape') {
    e.preventDefault()
    close()
  }
}

onMounted(() => window.addEventListener('keydown', onKey))
onBeforeUnmount(() => {
  window.removeEventListener('keydown', onKey)
  stopPreview()
})
</script>

