import { onBeforeUnmount, onMounted } from 'vue'

/**
 * Свайп от края экрана (для сенсорных столов/планшетов).
 * onSwipe('left' | 'right') — с какого края начался жест внутрь экрана.
 */
export function useEdgeSwipe(onSwipe, { edge = 32, distance = 70 } = {}) {
  let start = null

  const down = (e) => {
    if (e.pointerType === 'mouse') return
    const w = window.innerWidth
    if (e.clientX <= edge) start = { side: 'left', x: e.clientX, y: e.clientY }
    else if (e.clientX >= w - edge) start = { side: 'right', x: e.clientX, y: e.clientY }
    else start = null
  }

  const move = (e) => {
    if (!start) return
    const dx = e.clientX - start.x
    const dy = Math.abs(e.clientY - start.y)
    if (dy > distance) {
      start = null
      return
    }
    if ((start.side === 'left' && dx > distance) || (start.side === 'right' && dx < -distance)) {
      onSwipe(start.side)
      start = null
    }
  }

  const up = () => {
    start = null
  }

  onMounted(() => {
    window.addEventListener('pointerdown', down, { passive: true })
    window.addEventListener('pointermove', move, { passive: true })
    window.addEventListener('pointerup', up, { passive: true })
    window.addEventListener('pointercancel', up, { passive: true })
  })
  onBeforeUnmount(() => {
    window.removeEventListener('pointerdown', down)
    window.removeEventListener('pointermove', move)
    window.removeEventListener('pointerup', up)
    window.removeEventListener('pointercancel', up)
  })
}
