import { defineStore } from 'pinia'
import { hotStore } from './hmr'
import presets from '@/config/presets'
import { findPresetImage } from '@/library/mapImages'
import { hasStaticTrack, firstTrackOfCategory } from '@/library/audioLibrary'

export const DEFAULT_VIEW = Object.freeze({ x: 0, y: 0, scale: 1 })

function presetAudio(preset) {
  if (Array.isArray(preset.audio)) {
    const tracks = preset.audio.filter((id) => {
      if (!hasStaticTrack(id)) {
        console.warn(`[presets] трек не найден: ${id} (карта «${preset.name}»)`)
        return false
      }
      return true
    })
    return { mode: tracks.length ? 'tracks' : 'keep', tracks }
  }
  const auto = firstTrackOfCategory(preset.name)
  return auto ? { mode: 'tracks', tracks: [auto.id] } : { mode: 'keep', tracks: [] }
}

function presetImage(preset) {
  const found = findPresetImage(preset.image || preset.id)
  return found ? { url: found.url, name: found.file, temporary: false } : null
}

function fromPreset(preset) {
  return {
    id: preset.id,
    name: preset.name,
    icon: preset.icon || '🗺️',
    preset: true,
    image: presetImage(preset),
    fit: preset.fit || 'contain',
    rotation: 0,
    audio: presetAudio(preset),
    view: { ...DEFAULT_VIEW }
  }
}

/** blob:-ссылки живут до закрытия вкладки — освобождаем, когда картинка больше не нужна */
export function releaseImage(image) {
  if (image && image.temporary) URL.revokeObjectURL(image.url)
}

export function imageFromFile(file) {
  return { url: URL.createObjectURL(file), name: file.name, temporary: true }
}

function slugId(name) {
  const base =
    name
      .toLowerCase()
      .replace(/[^a-zа-яё0-9]+/gi, '-')
      .replace(/^-|-$/g, '')
      .slice(0, 24) || 'map'
  return `${base}-${Math.random().toString(36).slice(2, 6)}`
}

export const useMapsStore = defineStore('maps', {
  state: () => ({
    maps: presets.map(fromPreset)
  }),

  getters: {
    byId: (s) => (id) => s.maps.find((m) => m.id === id) || null,
    first: (s) => s.maps[0] || null
  },

  actions: {
    /** @returns {string} id новой карты */
    addMap(data) {
      const map = {
        id: slugId(data.name || 'Новая карта'),
        name: data.name || 'Новая карта',
        icon: data.icon || '🗺️',
        preset: false,
        image: data.image || null,
        fit: data.fit || 'contain',
        rotation: data.rotation || 0,
        audio: data.audio || { mode: 'keep', tracks: [] },
        view: { ...DEFAULT_VIEW }
      }
      this.maps.push(map)
      return map.id
    },

    updateMap(id, patch) {
      const map = this.byId(id)
      if (!map) return
      if ('image' in patch && patch.image !== map.image) {
        const old = map.image
        // дефолтную картинку пресета не освобождаем — её можно вернуть
        if (old && old.url !== (patch.image && patch.image.url)) releaseImage(old)
        map.view = { ...DEFAULT_VIEW }
      }
      Object.assign(map, patch)
    },

    setImage(id, image) {
      this.updateMap(id, { image })
    },

    removeMap(id) {
      const index = this.maps.findIndex((m) => m.id === id)
      if (index === -1 || this.maps[index].preset) return
      releaseImage(this.maps[index].image)
      this.maps.splice(index, 1)
    },

    moveMap(id, delta) {
      const from = this.maps.findIndex((m) => m.id === id)
      const to = from + delta
      if (from === -1 || to < 0 || to >= this.maps.length) return
      const [map] = this.maps.splice(from, 1)
      this.maps.splice(to, 0, map)
    },

    setView(id, view) {
      const map = this.byId(id)
      if (map) map.view = view
    },

    resetView(id) {
      this.setView(id, { ...DEFAULT_VIEW })
    },

    /** трек удалён — убираем его из привязок всех карт */
    forgetTrack(trackId) {
      for (const map of this.maps) {
        if (!map.audio.tracks.includes(trackId)) continue
        const tracks = map.audio.tracks.filter((id) => id !== trackId)
        map.audio = { mode: tracks.length || map.audio.mode !== 'tracks' ? map.audio.mode : 'keep', tracks }
      }
    }
  }
})

/** Исходная картинка пресета из src/assets/maps (или null) */
export function defaultImageFor(id) {
  const preset = presets.find((p) => p.id === id)
  return preset ? presetImage(preset) : null
}

hotStore(import.meta.webpackHot, useMapsStore)
